    {
      "citations": [
        {
          "event_id": "lite_evt_00057",
          "explanation": "The patient provided current symptom status including bleeding color/amount, pain, fever, and presyncope symptoms.",
          "quote": "没有鲜红很多血，也没有一边特别痛，没发烧，也没有头晕站不稳"
        },
        {
          "event_id": "lite_evt_00092",
          "explanation": "The doctor gave clear emergency escalation for worsening bleeding, pain, and hemodynamic symptoms.",
          "quote": "不要继续在门诊排队，直接去急诊"
        }
      ],
      "explanation": "Current risk was assessed from patient-reported symptoms and appropriately stratified: stable symptoms could proceed to medication verification, while worsening bleeding, severe pain, or systemic symptoms required urgent care.",
      "issue_kind": "none",
      "rc_id": "R1_current_risk_triage",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00033",
          "explanation": "The doctor explicitly avoided over-interpreting the unclear ultrasound and early pregnancy status.",
          "quote": "不能直接判断“稳定”或“不稳定”"
        },
        {
          "event_id": "lite_evt_00033",
          "explanation": "The doctor stated that true stability depends on fetal cardiac activity, growth, effusion trend, and symptoms.",
          "quote": "真正的稳定需要看到"
        }
      ],
      "explanation": "The doctor explained that early intrauterine pregnancy and effusion did not alone prove stability or failure, and tied prognosis to symptoms, fetal heart/gestational findings, and repeat assessment.",
      "issue_kind": "none",
      "rc_id": "R2_uncertain_result_interpretation",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00092",
          "explanation": "The doctor required original-clinician verification of progesterone injection and Duphaston details rather than patient self-adjustment.",
          "quote": "今天一定要让医生写清楚的三件事"
        },
        {
          "event_id": "lite_evt_00194",
          "explanation": "After verification, the doctor reinforced no double dosing and daily injection continuity.",
          "quote": "每次一片，不加倍补"
        }
      ],
      "explanation": "The medication confusion was safely reconciled through original-hospital verification, avoidance of unsupervised supplementation or community injection before dose confirmation, and later a confirmed dosing schedule.",
      "issue_kind": "none",
      "rc_id": "R3_medication_reconciliation_safety",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00168",
          "explanation": "The doctor specified the obstetric follow-up window.",
          "quote": "3到7天内回产科复诊"
        },
        {
          "event_id": "lite_evt_00168",
          "explanation": "The doctor explained that repeat ultrasound/fetal heart assessment would be decided at obstetric review based on symptoms and exam.",
          "quote": "再决定要不要开B超"
        }
      ],
      "explanation": "The follow-up plan identified obstetrics as the responsible service, gave a 3-7 day timing window, and linked reassessment to ultrasound/fetal-heart and symptom changes.",
      "issue_kind": "none",
      "rc_id": "R4_specific_followup_plan",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00033",
          "explanation": "The doctor addressed the blurry medication document with an executable re-photography plan.",
          "quote": "把模糊的药单重新拍一张清晰的照片"
        },
        {
          "event_id": "lite_evt_00033",
          "explanation": "The doctor also asked for drug packaging and repeat ultrasound documentation to resolve ambiguity.",
          "quote": "药盒、针剂包装也一起拍下来"
        }
      ],
      "explanation": "The document-quality friction was not ignored; the doctor asked for clearer medication/report photos and later directed the patient to bring original documents and drug boxes for in-person verification.",
      "issue_kind": "none",
